def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    current = chain_dict['aaa']
    result = []
    while current:
        next_token = current[0]
        result.append(next_token)
        current = chain_dict[next_token]

    return ','.join(result)
